    const oauth = weakRef.deref();
    if (!oauth) {
      oAuth2Objects.delete(weakRef);
      continue;
    }
    if (
      oauth.authorizationEndpoint == issuerDetails.authorizationEndpoint &&
      oauth.username == username &&
      scopeSet(oauth.scope).isSupersetOf(this._requiredScopes)
    ) {
